CREATE FUNCTION mawid_core.actor() RETURNS uuid LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$ SELECT actor_id FROM mawid_core.principals WHERE database_user=session_user $$;
CREATE FUNCTION mawid_core.has_role(w uuid,l uuid,needed text[]) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$ SELECT EXISTS(SELECT 1 FROM mawid_core.memberships m WHERE m.actor_id=mawid_core.actor() AND m.workspace_id=w AND m.revoked_at IS NULL AND (m.location_id IS NULL OR m.location_id=l) AND m.roles && needed) $$;
CREATE FUNCTION mawid_core.owns_customer(w uuid,c uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$ SELECT EXISTS(SELECT 1 FROM mawid_core.customer_profiles p WHERE p.workspace_id=w AND p.customer_id=c AND p.actor_id=mawid_core.actor() AND p.anonymized_at IS NULL) $$;
ALTER TABLE mawid_core.principals ENABLE ROW LEVEL SECURITY; ALTER TABLE mawid_core.principals FORCE ROW LEVEL SECURITY;
CREATE POLICY own_principal ON mawid_core.principals USING(database_user=session_user);
ALTER TABLE mawid_core.memberships ENABLE ROW LEVEL SECURITY; ALTER TABLE mawid_core.memberships FORCE ROW LEVEL SECURITY;
CREATE POLICY own_membership ON mawid_core.memberships USING(actor_id=mawid_core.actor());
ALTER TABLE mawid_core.organizations ENABLE ROW LEVEL SECURITY; ALTER TABLE mawid_core.organizations FORCE ROW LEVEL SECURITY;
CREATE POLICY organization_staff ON mawid_core.organizations USING(EXISTS(SELECT 1 FROM mawid_core.memberships m WHERE m.workspace_id=organizations.workspace_id AND m.actor_id=mawid_core.actor() AND m.revoked_at IS NULL)) WITH CHECK(EXISTS(SELECT 1 FROM mawid_core.memberships m WHERE m.workspace_id=organizations.workspace_id AND m.actor_id=mawid_core.actor() AND m.revoked_at IS NULL AND m.roles && ARRAY['manager']));
ALTER TABLE mawid_core.customer_profiles ENABLE ROW LEVEL SECURITY; ALTER TABLE mawid_core.customer_profiles FORCE ROW LEVEL SECURITY;
CREATE POLICY profiles_read ON mawid_core.customer_profiles FOR SELECT USING(actor_id=mawid_core.actor() OR mawid_core.has_role(workspace_id,NULL,ARRAY['manager','admin']));
CREATE POLICY profiles_write ON mawid_core.customer_profiles FOR INSERT WITH CHECK(mawid_core.has_role(workspace_id,NULL,ARRAY['manager']));
CREATE POLICY profiles_update ON mawid_core.customer_profiles FOR UPDATE USING(mawid_core.has_role(workspace_id,NULL,ARRAY['manager'])) WITH CHECK(mawid_core.has_role(workspace_id,NULL,ARRAY['manager']));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['locations','professionals','services','eligibility','opening_intervals','schedule_exceptions','professional_intervals'] LOOP EXECUTE format('ALTER TABLE mawid_core.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE mawid_core.%I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY scoped_read ON mawid_core.%I FOR SELECT USING(mawid_core.has_role(workspace_id,location_id,ARRAY[''manager'',''admin'',''professional'']))',t); IF t<>'locations' THEN EXECUTE format('CREATE POLICY scoped_insert ON mawid_core.%I FOR INSERT WITH CHECK(mawid_core.has_role(workspace_id,location_id,ARRAY[''manager'']))',t); EXECUTE format('CREATE POLICY scoped_update ON mawid_core.%I FOR UPDATE USING(mawid_core.has_role(workspace_id,location_id,ARRAY[''manager''])) WITH CHECK(mawid_core.has_role(workspace_id,location_id,ARRAY[''manager'']))',t); END IF; END LOOP; END $$;
ALTER TABLE mawid_core.bookings ENABLE ROW LEVEL SECURITY; ALTER TABLE mawid_core.bookings FORCE ROW LEVEL SECURITY;
CREATE POLICY scoped_booking ON mawid_core.bookings FOR SELECT USING(mawid_core.has_role(workspace_id,location_id,ARRAY['admin','manager','professional']) OR mawid_core.owns_customer(workspace_id,customer_id));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['allocations','booking_events','outbox','operation_references','idempotency_records','deletion_ledger'] LOOP EXECUTE format('ALTER TABLE mawid_core.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE mawid_core.%I FORCE ROW LEVEL SECURITY',t); END LOOP; END $$;
-- Internal capacity, audit, retries and erasure data stay default-deny for local actor roles.
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['import_jobs','export_jobs','transfer_audit'] LOOP EXECUTE format('ALTER TABLE mawid_core.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE mawid_core.%I FORCE ROW LEVEL SECURITY',t); END LOOP; END $$;
CREATE POLICY own_import ON mawid_core.import_jobs USING(actor_id=mawid_core.actor() AND mawid_core.has_role(workspace_id,location_id,ARRAY['manager'])) WITH CHECK(actor_id=mawid_core.actor() AND mawid_core.has_role(workspace_id,location_id,ARRAY['manager']));
CREATE POLICY own_export ON mawid_core.export_jobs USING(actor_id=mawid_core.actor() AND ((customer_id IS NOT NULL AND mawid_core.owns_customer(workspace_id,customer_id)) OR (customer_id IS NULL AND mawid_core.has_role(workspace_id,location_id,ARRAY['manager'])))) WITH CHECK(actor_id=mawid_core.actor() AND ((customer_id IS NOT NULL AND mawid_core.owns_customer(workspace_id,customer_id)) OR (customer_id IS NULL AND mawid_core.has_role(workspace_id,location_id,ARRAY['manager']))));
CREATE POLICY own_audit ON mawid_core.transfer_audit FOR SELECT USING(actor_id=mawid_core.actor() AND EXISTS(SELECT 1 FROM mawid_core.memberships m WHERE m.workspace_id=transfer_audit.workspace_id AND m.actor_id=mawid_core.actor() AND m.revoked_at IS NULL));
CREATE POLICY audit_insert ON mawid_core.transfer_audit FOR INSERT WITH CHECK(actor_id=mawid_core.actor() AND EXISTS(SELECT 1 FROM mawid_core.memberships m WHERE m.workspace_id=transfer_audit.workspace_id AND m.actor_id=mawid_core.actor() AND m.revoked_at IS NULL));
CREATE FUNCTION mawid_core.bump_configuration() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$ BEGIN UPDATE mawid_core.organizations SET configuration_version=configuration_version+1 WHERE workspace_id=NEW.workspace_id; RETURN NEW; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['customer_profiles','professionals','services','opening_intervals','schedule_exceptions','eligibility','professional_intervals'] LOOP EXECUTE format('CREATE TRIGGER configuration_changed AFTER INSERT OR UPDATE ON mawid_core.%I FOR EACH ROW EXECUTE FUNCTION mawid_core.bump_configuration()',t); END LOOP; END $$;
GRANT USAGE ON SCHEMA mawid_core TO mawid_local_actor;
GRANT SELECT ON mawid_core.principals,mawid_core.memberships,mawid_core.organizations,mawid_core.locations,mawid_core.customer_profiles,mawid_core.professionals,mawid_core.services,mawid_core.opening_intervals,mawid_core.schedule_exceptions,mawid_core.professional_intervals,mawid_core.eligibility,mawid_core.bookings,mawid_core.import_jobs,mawid_core.export_jobs,mawid_core.transfer_audit TO mawid_local_actor;
GRANT INSERT,UPDATE ON mawid_core.customer_profiles,mawid_core.professionals,mawid_core.services,mawid_core.opening_intervals,mawid_core.import_jobs TO mawid_local_actor;
GRANT INSERT ON mawid_core.export_jobs,mawid_core.transfer_audit TO mawid_local_actor;
GRANT UPDATE(configuration_version) ON mawid_core.organizations TO mawid_local_actor;
GRANT EXECUTE ON FUNCTION mawid_core.actor(),mawid_core.has_role(uuid,uuid,text[]),mawid_core.owns_customer(uuid,uuid),mawid_core.bump_configuration() TO mawid_local_actor;

REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA mawid_core FROM PUBLIC;
